98: function terrainColor(h, nx, nz, x, z, out) {
99:   if (h < -6) {
100:     out.copy(C.seaFloor);
101:     return out;
102:   }
103:   const slope = Math.min(1, Math.hypot(nx, nz) * 1.8);
104:   const variation = fbm2(x * 0.004, z * 0.004, 3, 5) * 0.5 + 0.5;
105: 
106:   if (h < 4) {
107:     out.copy(C.deepSand).lerp(C.sand, smoothstep(-6, 3, h));
108:   } else if (h < 16) {
109:     out.copy(C.sand).lerp(C.grass, smoothstep(8, 20, h));
110:   } else {
111:     out.copy(C.grass).lerp(C.grassDry, smoothstep(16, 180, h) * (0.35 + variation * 0.5));
112:     out.lerp(C.forest, smoothstep(0.45, 0.8, variation) * 0.65 * (1 - smoothstep(130, 300, h)));
113:     out.lerp(C.rock, smoothstep(220, 620, h) * 0.65 + slope * 0.55);
114:     out.lerp(C.rockDark, smoothstep(0.35, 0.9, slope) * 0.4);
115:     const snowLine = 820 + variation * 160;
116:     const snow = smoothstep(snowLine, snowLine + 180, h) * (1 - slope * 0.65);
117:     out.lerp(C.snow, Math.min(1, snow));
118:   }
119:   // gentle per-vertex tint so flat areas don't look like plastic
120:   out.multiplyScalar(0.94 + variation * 0.12);
121:   return out;
