135:   let p = 0;
136:   let c = 0;
137:   let u = 0;
138:   for (let iz = 0; iz <= segments; iz++) {
139:     const z = -size / 2 + (iz / segments) * size;
140:     for (let ix = 0; ix <= segments; ix++) {
141:       const x = -size / 2 + (ix / segments) * size;
142:       const h = heightAt(x, z);
143:       positions[p++] = x;
144:       positions[p++] = h;
145:       positions[p++] = z;
146: 
147:       const eps = 14;
148:       const nx = (heightAt(x - eps, z) - heightAt(x + eps, z)) / (2 * eps);
149:       const nz = (heightAt(x, z - eps) - heightAt(x, z + eps)) / (2 * eps);
150:       terrainColor(h, nx, nz, x, z, tmpColor);
151:       colors[c++] = tmpColor.r;
152:       colors[c++] = tmpColor.g;
153:       colors[c++] = tmpColor.b;
154: 
155:       uvs[u++] = ix / segments;
156:       uvs[u++] = iz / segments;
157:     }
158:   }
159: 
160:   const indices = [];
161:   for (let iz = 0; iz < segments; iz++) {
162:     for (let ix = 0; ix < segments; ix++) {
163:       const a = iz * (segments + 1) + ix;
164:       const b = a + 1;
165:       const d = a + segments + 1;
